head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
	var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
	var r = d(id); if (r) return r;
	var s = dd(P + id); r = d(s); if (r) return r;
	var g = s.indexOf('G_');
	if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
	return d(s.replace(P, ''));
};

scwin.trigger1_onclick = function(e) {
	wfm1.setSrc("/sample/common_link/wframe_SKT-476_(WSQ-1091)_WebSquare1.xml");
};

// id 중복 경고(엔진 E_comp_duplicated_Msg: logger 기록 + alert) 건수|DOM 중복 id 목록 - 정상이면 '0|'. 2026-11
scwin.dupCheck = function() {
	var L = String(WebSquare.logger.getLog()), seen = {}, dup = [];
	Array.prototype.forEach.call(document.querySelectorAll('[id]'), function(e) { if (seen[e.id]) dup.push(e.id); seen[e.id] = 1; });
	return (L.match(/is duplicated|중복사용|重複/g) || []).length + '|' + dup.join(',');
};
scwin.checkVal1 = function() {
	return scwin.__getDom($p.id + 'wfm1') != null;
};

scwin.checkVal2 = function() {
	return scwin.__getDom($p.id + 'wfm1_wfm1_input2') != null;
};
